];
const npcState=[];
function createNpc(def,i){const g=new THREE.Group();g.position.set(def.x,0,def.z);scene.add(g);
  const skin=mat(def.color),shirt=mat(i%2?0x47586a:0x865d42),pants=mat(0x4a4d4b),shoe=mat(0x22282b);
  box(g,0,1.2,0,.6,1.1,.38,shirt);box(g,0,2.15,0,.48,.48,.46,skin);box(g,0,1.05,.2,.28,.56,.12,pants);box(g,0,.52,.22,.38,.54,.18,shoe);box(g,0,1.05,-.22,.38,.52,.12,pants);box(g,0,.52,-.22,.38,.54,.18,shoe);
  // A subtle loop keeps each NPC in motion without obstructing the walkable roads.
  const target={x:def.home[0]+(rand()-.5)*10,z:def.home[1]+(rand()-.5)*10};
  const npc={...def,group:g,target,dir:0,body:skin,walk:rand()*Math.PI*2};
  npcState.push(npc); return npc;
}
for(let i=0;i<npcDefs.length;i++)createNpc(npcDefs[i],i);

function npcBounds(npc){return {x:npc.x, z:npc.z, w:1.2, d:1.2};}
function tickNpc(npc,dt){const dx=npc.target.x-npc.x;const dz=npc.target.z-npc.z;const dist=Math.hypot(dx,dz);if(dist<.6||Math.random()<.008){const r=0.8+rand()*1.8;const a=rand()*Math.PI*2;npc.target={x:npc.home[0]+Math.cos(a)*r,z:npc.home[1]+Math.sin(a)*r}};
  const speed=npc.speed*(1+Math.sin((npc.walk+=dt*1.6))*0.08);const nx=dx/(dist||1),nz=dz/(dist||1);const mvx=nx*speed*dt,mvz=nz*speed*dt;
  const nextX=npc.x+mvx,nextZ=npc.z+mvz;
  if(!collides(nextX,npc.z))npc.x=nextX; if(!collides(npc.x,nextZ))npc.z=nextZ;
  if(Math.abs(dx)+Math.abs(dz)>0.05){npc.dir=Math.atan2(dx,dz);}
  npc.group.position.set(npc.x,0,npc.z);npc.group.rotation.y=-npc.dir+Math.PI/2;
  const bob=Math.abs(Math.sin(npc.walk*2.3))*0.08; npc.group.position.y=bob;}
